"""Sphinx directives for images generated by an executing gallery build."""

from docutils.parsers.rst.directives.images import Image


class SimulationImage(Image):
    """Create an image node only when fresh simulation media is enabled.

    Sphinx collects image paths before it removes ``only`` nodes. Guarding
    node creation keeps clean text-only builds free of missing-image warnings.
    """

    def run(self):
        if not self.state.document.settings.env.config.jaxdem_visuals_enabled:
            return []
        return super().run()
